+        emitter.mount(root, Environment.DEFAULT);
+        assertEquals("a:scoped", lastText(sink.frame()));
+
+        show.set(false);
+        assertEquals("b:scoped", lastText(sink.frame()), "the captured scope is re-applied");
+    }
