+        WritableSignal<Integer> n = Signals.signal(1);
+        View root = View.of(() -> switch (n.get()) {
+            case 1 -> Text.make(t -> t.text("same"));
+            case 2 -> Text.make(t -> t.text("same"));
+            default -> Text.make(t -> t.text("other"));
