+        Emitter emitter = new Emitter(sink);
+        WritableSignal<Integer> mode = Signals.signal(1);
+        View root = View.of(() -> mode.get() == 1 ? Text.make(t -> t.text("A")) : null);
+        emitter.mount(root, Environment.DEFAULT);
