+        ProtocolFrame delta = sink.frame();
+        assertEquals(1, countOps(delta, Categories.TREE, Commands.Tree.REMOVE_CHILD));
+        assertEquals(1, countOps(delta, Categories.TREE, Commands.Tree.DELETE_NODE));
