         CountDownLatch senderEntered = new CountDownLatch(1);
         DeltaBatcher batcher = new DeltaBatcher(60_000, 1_000_000, bytes -> {
             sent.add(bytes);
             senderEntered.countDown();
             try {
                 Thread.sleep(500);
             } catch (InterruptedException ignored) {
                 Thread.currentThread().interrupt();
