         long t0 = System.nanoTime();
         batcher.append(new ProtocolFrame(List.of(new Opcode(
                 Categories.PARAMETER, Commands.Parameter.SET_TEXT, 0, 2, 0, 0)), new byte[0]));
         long elapsedMs = (System.nanoTime() - t0) / 1_000_000;
