     /// Set a node's text content via the arena.
     pub fn set_text(&mut self, node_id: u32, text: &str) -> Result<u32, RingError> {
         let arena_ref = arena_fn::alloc_str(self.arena, self.header, text).map_err(|_| RingError::Full)?;
