     pub fn drain_events(&mut self) -> Vec<Event> {
         let mask = self.mask();
         let ops = ring_fn::read_events(&self.event_slots, self.header, mask, usize::MAX);
         ops.into_iter()
             .filter_map(|op| crate::events::decode_event(&op, self.event_arena))
             .collect()
     }

