         let renderer = HtmlRenderer::new();
         let html = renderer.render_fragment(&opcodes, &strings, 1);
         assert!(
             html.contains(&format!(
-                "data-pathland-id=\"1\" style=\"{MEDIA_CONTROLLER_SHELL_STYLE}\""
