     PL_SIZE_NONE = 0,  // absent -> natural size / greedy-primitive / propagate
     PL_SIZE_FILL = 1,  // FILL (-1) -> expand
     PL_SIZE_FIXED = 2, // a fixed points box -> bounds the subtree
     PL_SIZE_HUG = 3,   // HUG_CONTENT (-2) -> natural size, overrides greed
