         // 3. Child order (parents before children already exist), THEN props:
         //    the C++ layer attaches a widget to its final parent before its
         //    WIDTH/HEIGHT/ALIGNMENT arrive, so FILL/stretch resolve against the
         //    real parent (a Layout/positioner/window) instead of the create-time
         //    contentItem placeholder. The shared core's DELETE_NODE leaves a
         //    ghost in the parent's child list, so filter to live nodes.
         for &id in &order {
             let node = self.tree.node(id).unwrap();
             let children: Vec<u32> = node
                 .children
                 .iter()
                 .copied()
                 .filter(|c| self.tree.nodes.contains_key(c))
                 .collect();
             let prev = self.sent_children.entry(id).or_default();
             cmds.extend(children_diff(id, prev, &children));
             *prev = children;
         }

         // 4. Roots are children of the pseudo-parent 0 (window contentItem).
         let mut roots: Vec<u32> = order
             .iter()
             .copied()
             .filter(|&id| self.tree.node(id).map_or(false, |n| n.parent.is_none()))
             .collect();
         roots.sort_unstable();
         let prev_roots = self.sent_children.entry(CONTENT_ITEM).or_default();
         cmds.extend(children_diff(CONTENT_ITEM, prev_roots, &roots));
         *prev_roots = roots;

         // 5. Text + property deltas (after the widget is attached to its final
         //    parent). On any property change we re-send the node's *complete*
         //    property set (preceded by RESET_NODE), so the C++ layer can reset
         //    removed properties to its renderer defaults.
         for &id in &order {
             let node = self.tree.node(id).unwrap();
             let s = self.sent.get_mut(&id).unwrap();

             if s.text != node.text {
                 cmds.push(Command::set_text(id, node.text.as_deref().unwrap_or("")));
                 s.text = node.text.clone();
             }
             if node.date != s.date {
                 if let Some((days, millis)) = node.date {
                     cmds.push(Command::set_date(id, days, millis));
                 }
                 s.date = node.date;
             }
             let strings = string_props(node);
             if node.properties != s.props || strings != s.strings {
                 cmds.push(Command::reset_node(id));
                 // Emit numeric props in a deterministic order with VALUE last:
                 // Qt Quick clamps a control's `value` when `from`/`to` aren't
                 // configured yet, so min/max must land before the value.
                 let mut props: Vec<(u16, u32)> =
                     node.properties.iter().map(|(k, v)| (*k, *v)).collect();
                 // Order: TEXT_STYLE first (a base typography), then the rest
                 // (raw font modifiers override it), with VALUE last (Qt Quick
                 // clamps a control's value when from/to aren't configured yet).
                 use pathland_core::property_id::{TEXT_STYLE, VALUE};
                 props.sort_by_key(|(p, _)| (*p == VALUE, *p != TEXT_STYLE, *p));
                 for (prop, value) in &props {
                     let vt = value_type_for(*prop);
                     cmds.push(Command::set_property(id, *prop, vt, *value));
                 }
                 for (prop, value) in &strings {
                     cmds.push(Command::set_string_property(id, *prop, value));
                 }
                 s.props = node.properties.clone();
                 s.strings = strings;
             }
         }

+        // 6. Window metadata (`META::SET_WINDOW_METADATA`): renderer-global, not
+        //    a node. Only a changed title is forwarded; Qt has no description or
+        //    locale slot. The string stays in `self` so the batch can borrow it.
+        let title = self.tree.window().title.clone();
+        if title != self.sent_window_title {
+            self.sent_window_title = title;
+            if let Some(title) = self.sent_window_title.as_deref() {
+                cmds.push(Command::set_window_title(title));
+            }
+        }
+
         cmds
     }

     fn pre_order(&self) -> Vec<u32> {
         let mut order = Vec::new();
         let mut roots: Vec<u32> = self
             .tree
             .nodes
             .keys()
             .copied()
             .filter(|&id| self.tree.node(id).map_or(false, |n| n.parent.is_none()))
             .collect();
         roots.sort_unstable();
         for r in roots {
             self.walk(r, &mut order);
         }
         order
     }

     fn walk(&self, id: u32, out: &mut Vec<u32>) {
         // Guard against ghost children (a node deleted from `tree.nodes` but
         // still listed in a parent's `children` after DELETE_NODE).
         if !self.tree.nodes.contains_key(&id) {
             return;
         }
         out.push(id);
         if let Some(node) = self.tree.node(id) {
             for c in node.children.clone() {
                 self.walk(c, out);
             }
         }
     }
 }

 /// The string-valued properties a node sends to the C++ layer: its decoded
 /// strings plus `LIST` properties serialized as CSV (today a `FIT_QUERY`
 /// threshold table, which the Qt layer parses to measure a fit slot).
 fn string_props(node: &HostNode) -> HashMap<u16, String> {
     let mut props = node.strings.clone();
     for (prop, values) in &node.lists {
         let csv = values
             .iter()
             .map(|v| v.to_string())
             .collect::<Vec<_>>()
             .join(",");
         props.insert(*prop, csv);
     }
     props
 }

 /// The opcode wire's value type for a property (same mapping the emit side
 /// uses; the C++ layer needs it to interpret the raw u32).
 fn value_type_for(prop: u16) -> u8 {
     if is_f32_property(prop) {
         value_type::F32
     } else {
         value_type::U32
     }
 }

 fn is_f32_property(prop: u16) -> bool {
     matches!(
         prop,
         pathland_core::property_id::SPACING
             | pathland_core::property_id::SHAPE_KIND
             | pathland_core::property_id::WIDTH
             | pathland_core::property_id::HEIGHT
             | pathland_core::property_id::FONT_SIZE
             | pathland_core::property_id::FONT_STYLE
             | pathland_core::property_id::OPACITY
             | pathland_core::property_id::Z_INDEX
             | pathland_core::property_id::BORDER_WIDTH
             | pathland_core::property_id::BORDER_RADIUS
             | pathland_core::property_id::PADDING
             | pathland_core::property_id::PADDING_TOP
             | pathland_core::property_id::PADDING_RIGHT
             | pathland_core::property_id::PADDING_BOTTOM
             | pathland_core::property_id::PADDING_LEFT
             | pathland_core::property_id::VALUE
             | pathland_core::property_id::MIN_VALUE
             | pathland_core::property_id::MAX_VALUE
             | pathland_core::property_id::STEP_VALUE
             | pathland_core::property_id::PROGRESS
             | pathland_core::property_id::NAV_CHROME
             | pathland_core::property_id::TRANSITION
             | pathland_core::property_id::OFFSET_X
             | pathland_core::property_id::OFFSET_Y
             | pathland_core::property_id::POSITION_X
             | pathland_core::property_id::POSITION_Y
             | pathland_core::property_id::MIN_WIDTH
             | pathland_core::property_id::IDEAL_WIDTH
             | pathland_core::property_id::MAX_WIDTH
             | pathland_core::property_id::MIN_HEIGHT
             | pathland_core::property_id::IDEAL_HEIGHT
             | pathland_core::property_id::MAX_HEIGHT
             | pathland_core::property_id::LAYOUT_PRIORITY
             | pathland_core::property_id::ASPECT_RATIO
             | pathland_core::property_id::CONTENT_MODE
             | pathland_core::property_id::MINIMUM_SCALE_FACTOR
             | pathland_core::property_id::GRID_COLUMNS
             | pathland_core::property_id::GRID_ROWS
             | pathland_core::property_id::TEXT_ALIGNMENT
             | pathland_core::property_id::MEDIA_POSITION
             | pathland_core::property_id::MEDIA_VOLUME
             | pathland_core::property_id::MEDIA_RATE
     )
 }

 /// Minimal child-order delta: for each index where the old and new children
 /// differ, remove the stale child and insert the new one at that index.
 fn children_diff(parent: u32, prev: &[u32], next: &[u32]) -> Vec<Command> {
     let mut cmds = Vec::new();
     let len = prev.len().max(next.len());
     for i in 0..len {
         let old = prev.get(i).copied();
         let new = next.get(i).copied();
         if old == new {
             continue;
         }
         if let Some(c) = old {
             cmds.push(Command::remove_child(parent, c));
         }
         if let Some(c) = new {
             cmds.push(Command::insert_child(parent, c, i as u32));
         }
     }
     cmds
 }

